<?php
declare(strict_types=1);namespace App\Controller;use App\Http\UserPortalResponseFactory;use App\Service\AppRoleService;use App\View\GatewayPageRenderer;use Hyperf\DbConnection\Db;use Psr\Http\Message\ResponseInterface;
final class GatewayStatusController extends AbstractController{public function __construct(private GatewayPageRenderer$pages,private AppRoleService$roles,private UserPortalResponseFactory$responses,private Db$db){}public function routes():ResponseInterface{$s=$this->session();$r=$this->rows($this->db->select('SELECT e.`method`,e.`path`,e.`name`,v.`version` FROM `api_endpoints` e INNER JOIN `api_versions` v ON v.`id`=e.`api_version_id` AND v.`status`=\'published\' WHERE e.`deleted_at` IS NULL ORDER BY e.`id` DESC LIMIT 100'));return$this->responses->html($this->pages->routes($s,$r));}public function calls():ResponseInterface{$s=$this->session();return$this->responses->html($this->pages->calls($s,$this->rows($this->db->select('SELECT `event_id`,`subscription_id`,`status_code`,`duration_ms`,`occurred_at` FROM `gateway_call_events` WHERE `deleted_at` IS NULL ORDER BY `occurred_at` DESC LIMIT 100'))));}public function usage():ResponseInterface{$s=$this->session();return$this->responses->html($this->pages->usage($s,$this->rows($this->db->select('SELECT `subscription_id`,`period_id`,`call_count` FROM `usage_aggregates` WHERE `deleted_at` IS NULL ORDER BY `period_id` DESC LIMIT 100'))));}public function nodes():ResponseInterface{$s=$this->session();return$this->responses->html($this->pages->nodes($s,['role'=>$this->roles->current()]));}/** @return array<string,mixed> */private function session():array{$s=$this->request->getAttribute('user_session');return is_array($s)?$s:[];}/** @param list<object|array<string,mixed>>$r @return list<array<string,mixed>> */private function rows(array$r):array{return array_map(static fn(object|array$v):array=>is_object($v)?get_object_vars($v):$v,$r);}}
